<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Learning Center — EngineerLaunch</title><style>:root{--ink:#10213e;--muted:#6b7890;--line:#dfe6f1}*{box-sizing:border-box}body{margin:0;background:#f7f9fd;color:var(--ink);font-family:Inter,system-ui,sans-serif}a{text-decoration:none;color:inherit}.wrap{width:min(1180px,calc(100% - 36px));margin:auto}.hero{padding:62px 0 50px;background:linear-gradient(130deg,#eef6ff,#fff 52%,#f3efff);text-align:center}.eyebrow{display:inline-block;padding:8px 14px;border-radius:999px;background:#e7eeff;color:#2563eb;font-size:12px;font-weight:800}.hero h1{margin:18px 0 12px;font-size:clamp(38px,5vw,60px);letter-spacing:-2px}.hero h1 span{color:#7047eb}.hero p{max-width:680px;margin:auto;color:var(--muted);line-height:1.7}.paths{padding:48px 0 75px}.heading{text-align:center;margin-bottom:28px}.heading h2{margin:0 0 8px;font-size:31px}.heading p{margin:0;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:18px}.card{display:flex;min-height:300px;flex-direction:column;padding:25px;border:2px solid transparent;border-radius:18px;background:#fff;box-shadow:0 10px 30px #1635680d;transition:.22s}.card:hover{transform:translateY(-7px);border-color:var(--accent);box-shadow:0 20px 42px #1635681c}.icon{display:grid;place-items:center;width:58px;height:58px;border-radius:15px;background:var(--accent);color:#fff;font-size:18px;font-weight:900}.card h3{margin:22px 0 9px;font-size:22px}.card p{margin:0;color:var(--muted);font-size:14px;line-height:1.65}.meta{margin-top:18px;color:var(--accent);font-size:13px;font-weight:800}.open{margin-top:auto;padding-top:22px;color:var(--accent);font-weight:800}.actions{text-align:center;margin-top:30px}.practice{display:inline-block;padding:12px 18px;border-radius:9px;background:#10213e;color:#fff;font-weight:800}@media(max-width:950px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:580px){.grid{grid-template-columns:1fr}}</style></head><body><section class="hero"><div class="wrap"><span class="eyebrow">Interview preparation</span><h1>Choose what you want to <span>learn.</span></h1><p>Focused learning paths with topic-wise questions, practical concepts and a clear interview roadmap.</p></div></section><main class="wrap paths"><div class="heading"><h2>Start your learning path</h2><p>Select a card to open its dedicated curriculum page.</p></div><div class="grid">@foreach($tracks as $slug=>$track)<a class="card" style="--accent:{{$track['color']}}" href="{{route('learning.track',$slug)}}"><div class="icon">{{$track['icon']}}</div><h3>{{$track['title']}}</h3><p>{{$track['description']}}</p><div class="meta">{{count($track['topics'])}} topics · {{collect($track['topics'])->sum(fn($topic)=>count($topic['questions']))}} questions</div><div class="open">Open {{$track['title']}} →</div></a>@endforeach</div><div class="actions"><a class="practice" href="{{route('practice')}}">Open live practice editor</a></div></main></body></html>
